-- create_table users
CREATE TABLE "public"."Users" (
  "ID" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "Slug Value" text GENERATED ALWAYS AS (lower("Email Address")) STORED NOT NULL,
  "Email Address" varchar(320) NOT NULL DEFAULT 'n/a',
  PRIMARY KEY ("ID")
);
COMMENT ON COLUMN "public"."Users"."Email Address" IS 'Login address';

-- rename_table users to accounts
ALTER TABLE "public"."Users" RENAME TO "Accounts";

-- add_column display_name
ALTER TABLE "public"."Users" ADD COLUMN "Display Name" varchar(120) NOT NULL DEFAULT FALSE;
COMMENT ON COLUMN "public"."Users"."Display Name" IS 'Shown in lists';

-- alter_column email
ALTER TABLE "public"."Users" ALTER COLUMN "Email Address" TYPE varchar(500);
ALTER TABLE "public"."Users" ALTER COLUMN "Email Address" SET NOT NULL;
ALTER TABLE "public"."Users" ALTER COLUMN "Email Address" SET DEFAULT 'n/a';
COMMENT ON COLUMN "public"."Users"."Email Address" IS 'Primary address';

-- rename_column email
ALTER TABLE "public"."Users" RENAME COLUMN "Email Address" TO "Email";

-- create_partial_index users_active
CREATE UNIQUE INDEX "Users Active Index" ON "public"."Users" USING btree ("Email") WHERE ("active" = TRUE);

-- add_check_constraint users_email
ALTER TABLE "public"."Users" ADD CONSTRAINT "users_email_check" CHECK ("Email" <> '');

-- drop_check_constraint users_email
ALTER TABLE "public"."Users" DROP CONSTRAINT "users_email_check";

-- drop_table accounts
DROP TABLE "public"."Accounts";

